from typing import List, Optional

import os


def translate_strings(strings: List[str], target_language: str, source_language: Optional[str] = None) -> List[str]:
    """
    Translate a list of strings while preserving order using DeepL API.

    Environment:
        DEEPL_AUTH_KEY: DeepL authentication key
    """
    try:
        import deepl
    except ImportError as e:
        raise ImportError("The deepl package is required. Install it with `pip install deepl`.") from e

    auth_key = os.getenv("DEEPL_AUTH_KEY")
    if not auth_key:
        raise ValueError("Missing DeepL API key. Set the DEEPL_AUTH_KEY environment variable.")

    translator = deepl.Translator(auth_key)

    if not strings:
        return []

    kwargs = {}
    if source_language:
        kwargs["source_lang"] = source_language
    kwargs["target_lang"] = target_language

    results = translator.translate_text(strings, **kwargs)

    if isinstance(results, list):
        return [item.text for item in results]
    return [results.text]
